create extension if not exists pgcrypto;
create table if not exists leads(id uuid primary key default gen_random_uuid(),company text not null,contact_name text,email text,phone text,city text default '',country text default '',service text not null default 'Both',source text default 'Manual',status text not null default 'New',estimated_value numeric default 0,website text,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists tasks(id uuid primary key default gen_random_uuid(),title text not null,due_date date,priority text default 'Medium',status text default 'Open',lead_id uuid references leads(id) on delete set null,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists projects(id uuid primary key default gen_random_uuid(),name text not null,client text not null,kind text default 'Video',stage text default 'Brief',deadline date,budget numeric default 0,progress integer default 0,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists assets(id uuid primary key default gen_random_uuid(),symbol text not null,name text not null,asset_type text default 'Stock',quantity numeric default 0,buy_price numeric default 0,current_price numeric default 0,purchased_at date,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists activities(id uuid primary key default gen_random_uuid(),lead_id uuid references leads(id) on delete cascade,kind text default 'Note',summary text not null,created_at timestamptz default now());
alter table leads enable row level security;alter table tasks enable row level security;alter table projects enable row level security;alter table assets enable row level security;alter table activities enable row level security;

